<?php
if(!defined('ABSPATH'))exit;
final class Hamnna_Scraper{
 const OPT='hamnna_scraper_settings',LOG='hamnna_scraper_logs',QUEUE='hamnna_scraper_queue',LOCK='hamnna_scraper_lock',CRON='hamnna_scraper_cron',SOURCE_HOST='hamnna.ir',SCHEMA=3;
 public static function cron_schedules($s){$s['hamnna_10min']=['interval'=>10*MINUTE_IN_SECONDS,'display'=>'Hamnna - Every 10 minutes'];return$s;}
 public static function defaults(){return['source'=>'https://hamnna.ir','batch'=>10,'enabled'=>1,'import_images'=>1,'publish'=>1,'skip_existing'=>1,'debug'=>0,'image_limit'=>8,'http_timeout'=>25];}
 public static function settings(){return wp_parse_args(get_option(self::OPT,[]),self::defaults());}
 public static function activate(){if(!get_option(self::OPT))add_option(self::OPT,self::defaults(),'','no');if(!get_option(self::LOG))add_option(self::LOG,[],'','no');self::schedule();}
 public static function deactivate(){wp_clear_scheduled_hook(self::CRON);delete_transient(self::LOCK);}
 public static function schedule(){wp_clear_scheduled_hook(self::CRON);if(self::settings()['enabled'])wp_schedule_event(time()+60,'hamnna_10min',self::CRON);}
 public static function admin_init(){register_setting('hamnna_scraper',self::OPT,['sanitize_callback'=>[__CLASS__,'sanitize'],'default'=>self::defaults()]);}
 public static function sanitize($in){$d=self::defaults();$in=is_array($in)?$in:[];$o=$d;$o['source']='https://'.self::SOURCE_HOST;$o['batch']=max(1,min(50,absint($in['batch']??10)));foreach(['enabled','import_images','publish','skip_existing','debug']as$k)$o[$k]=empty($in[$k])?0:1;$o['image_limit']=max(0,min(12,absint($in['image_limit']??8)));$o['http_timeout']=max(10,min(60,absint($in['http_timeout']??25)));self::schedule_after_settings_save($o['enabled']);return$o;}
 private static function schedule_after_settings_save($enabled){wp_clear_scheduled_hook(self::CRON);if($enabled)wp_schedule_event(time()+60,'hamnna_10min',self::CRON);}
 public static function admin_menu(){add_menu_page('اسکرپر همنا','اسکرپر همنا','manage_woocommerce','hamnna-scraper',[__CLASS__,'page'],'dashicons-update',56);}
 private static function card($t,$v){echo'<div class="ham-card"><span>'.esc_html($t).'</span><strong>'.esc_html($v).'</strong></div>';}
 public static function page(){if(!current_user_can('manage_woocommerce'))return;$s=self::settings();$l=get_option(self::LOG,[]);$q=get_option(self::QUEUE,[]);$next=wp_next_scheduled(self::CRON);$price=get_transient('hamnna_price_result');echo'<style>.ham-wrap{max-width:1250px}.ham-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:18px 0}.ham-card{background:#fff;border:1px solid #d9e2d9;border-radius:14px;padding:18px;box-shadow:0 5px 18px rgba(86,159,96,.12)}.ham-card span{display:block}.ham-card strong{display:block;font-size:23px;margin-top:8px;color:#569f60}.ham-tabs{display:flex;gap:8px;margin:20px 0}.ham-tab{background:#fff;border:1px solid #569f60;padding:12px 20px;border-radius:10px;cursor:pointer;font-weight:700}.ham-tab.active{background:#569f60;color:#fff}.ham-panel{background:#fff;border:1px solid #d9e2d9;border-radius:16px;padding:24px;box-shadow:0 5px 20px rgba(86,159,96,.08)}.ham-table{width:100%;border-collapse:collapse}.ham-table th,.ham-table td{padding:10px;border-bottom:1px solid #eee;text-align:right}.ham-ok{color:#569f60;font-weight:700}.ham-warning{padding:14px;border-radius:10px;background:#f7fbf7;border-right:4px solid #569f60;margin:15px 0}</style><div class="wrap ham-wrap" dir="rtl"><h1>اسکرپر محصولات همنا</h1><div class="ham-grid">';self::card('وضعیت',$s['enabled']?'فعال 🟢':'خاموش 🔴');self::card('صف محصولات',count($q));self::card('اجرای بعدی',$next?wp_date('Y-m-d H:i',$next):'—');self::card('آخرین اجرا',!empty($l[0]['time'])?$l[0]['time']:'—');echo'</div><div class="ham-tabs"><button type="button" class="ham-tab active" onclick="hamTab(1)">۱. همگام‌سازی محصولات</button><button type="button" class="ham-tab" onclick="hamTab(2)">۲. به‌روزرسانی قیمت‌ها</button></div><section id="ham-tab-1" class="ham-panel"><h2>همگام‌سازی محصولات — هر ۱۰ دقیقه</h2><div class="ham-warning">فقط محصولات جدید اسکرپ و وارد می‌شوند. محصولی که قبلاً با شناسه/آدرس hamnna.ir وارد شده باشد دوباره اسکرپ نمی‌شود. محصولات ناموجود نیز وارد نمی‌شوند.</div><p><a class="button button-primary" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=hamnna_scraper_run'),'hamnna_run')).'">اجرای دستی همین حالا</a> <a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=hamnna_scraper_reset_queue'),'hamnna_reset')).'">اسکن کامل محصولات</a></p><h3>گزارش دقیق</h3><table class="ham-table"><thead><tr><th>زمان</th><th>بررسی</th><th>جدید</th><th>قبلاً موجود</th><th>ناموجود</th><th>خطا</th><th>زمان</th></tr></thead><tbody>';foreach(array_slice(is_array($l)?$l:[],0,40)as$x){if(!empty($x['price_sync']))continue;echo'<tr><td>'.esc_html($x['time']??'').'</td><td>'.esc_html($x['checked']??0).'</td><td class="ham-ok">'.esc_html($x['new']??0).'</td><td>'.esc_html($x['existing']??0).'</td><td>'.esc_html($x['unavailable']??0).'</td><td>'.esc_html($x['errors']??0).'</td><td>'.esc_html($x['seconds']??0).'s</td></tr>';}echo'</tbody></table></section><section id="ham-tab-2" class="ham-panel" style="display:none"><h2>به‌روزرسانی دقیق قیمت‌ها</h2><div class="ham-warning"><strong>قیمت بسیار مهم است:</strong> قیمت از خود صفحه محصول در hamnna.ir خوانده می‌شود و بدون ضرب در ۱۰، ۱۰۰ یا تبدیل ریال/تومان در WooCommerce ذخیره می‌شود. نمونه: <b>۱۸۰.۰۰۰ تومان → 180000</b>.</div><p><a class="button button-primary" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=hamnna_price_sync'),'hamnna_price_sync')).'">💰 به‌روزرسانی قیمت همه محصولات</a></p>';if(is_array($price)){echo'<div class="ham-grid">';self::card('بررسی‌شده',$price['checked']??0);self::card('قیمت تغییرکرده',$price['updated']??0);self::card('بدون تغییر',$price['unchanged']??0);self::card('بدون قیمت',$price['missing']??0);self::card('خطا',$price['errors']??0);self::card('زمان اجرا',($price['seconds']??0).'s');echo'</div>';if(!empty($price['items'])){echo'<h3>جزئیات تغییر قیمت</h3><table class="ham-table"><thead><tr><th>محصول</th><th>قیمت قبلی</th><th>قیمت جدید</th></tr></thead><tbody>';foreach(array_slice($price['items'],0,100)as$i)echo'<tr><td>'.esc_html($i['title']).'</td><td>'.esc_html(number_format_i18n((float)$i['old'],0)).'</td><td class="ham-ok">'.esc_html(number_format_i18n((float)$i['new'],0)).'</td></tr>';echo'</tbody></table>';}}echo'</section><script>function hamTab(n){document.querySelectorAll(".ham-panel").forEach(function(x){x.style.display="none"});document.querySelectorAll(".ham-tab").forEach(function(x){x.classList.remove("active")});document.getElementById("ham-tab-"+n).style.display="block";document.querySelectorAll(".ham-tab")[n-1].classList.add("active")}</script></div>';}
 public static function manual_run(){if(!current_user_can('manage_woocommerce')||!check_admin_referer('hamnna_run'))wp_die('دسترسی غیرمجاز');self::run();wp_safe_redirect(admin_url('admin.php?page=hamnna-scraper'));exit;}
 public static function reset_queue(){if(!current_user_can('manage_woocommerce')||!check_admin_referer('hamnna_reset'))wp_die('دسترسی غیرمجاز');self::discover();wp_safe_redirect(admin_url('admin.php?page=hamnna-scraper'));exit;}
 public static function clear_logs(){if(!current_user_can('manage_woocommerce')||!check_admin_referer('hamnna_clear'))wp_die('دسترسی غیرمجاز');update_option(self::LOG,[],false);wp_safe_redirect(admin_url('admin.php?page=hamnna-scraper'));exit;}
 public static function price_sync_action(){if(!current_user_can('manage_woocommerce')||!check_admin_referer('hamnna_price_sync'))wp_die('دسترسی غیرمجاز');set_transient('hamnna_price_result',self::sync_prices(),10*MINUTE_IN_SECONDS);wp_safe_redirect(admin_url('admin.php?page=hamnna-scraper'));exit;}
 public static function run_cron(){self::run();}
 public static function run(){if(!class_exists('WooCommerce')){self::log(['errors'=>1,'message'=>'WooCommerce is not active.']);return;}if(get_transient(self::LOCK))return;set_transient(self::LOCK,1,30*MINUTE_IN_SECONDS);$start=microtime(true);$st=['checked'=>0,'new'=>0,'existing'=>0,'unavailable'=>0,'errors'=>0,'seconds'=>0];try{$q=get_option(self::QUEUE,[]);if(!is_array($q)||empty($q)){self::discover();$q=get_option(self::QUEUE,[]);} $s=self::settings();$work=array_splice($q,0,$s['batch']);update_option(self::QUEUE,array_values($q),false);foreach($work as$url){$url=self::normalize_product_url($url);if(!$url){$st['errors']++;continue;}$st['checked']++;$sid=self::source_id($url);if(self::exists($sid,$url)){$st['existing']++;continue;}$p=self::scrape($url);if(is_wp_error($p)){$st['errors']++;self::debug_log('scrape',$url,$p->get_error_message());continue;}if(!$p['available']){$st['unavailable']++;continue;}$i=self::import($p,$sid);if(is_wp_error($i)){$st['errors']++;self::debug_log('import',$url,$i->get_error_message());}else$st['new']++;}}catch(Throwable$e){$st['errors']++;self::debug_log('fatal','',$e->getMessage());}delete_transient(self::LOCK);$st['seconds']=round(microtime(true)-$start,2);self::log($st);}
 private static function sync_prices(){$start=microtime(true);$r=['checked'=>0,'updated'=>0,'unchanged'=>0,'missing'=>0,'errors'=>0,'seconds'=>0,'items'=>[]];$q=new WP_Query(['post_type'=>'product','post_status'=>'any','fields'=>'ids','posts_per_page'=>-1,'no_found_rows'=>true,'meta_query'=>[['key'=>'_hamnna_source_url','compare'=>'EXISTS']]]);foreach($q->posts as$id){$r['checked']++;$url=self::normalize_product_url(get_post_meta($id,'_hamnna_source_url',true));if(!$url){$r['errors']++;continue;}$p=self::scrape($url);if(is_wp_error($p)||$p['price']===''){ $r['missing']++;continue;}$product=wc_get_product($id);if(!$product){$r['errors']++;continue;}$old=(string)$product->get_regular_price();$new=(string)$p['price'];if((float)$old!==(float)$new){$product->set_regular_price($new);$product->set_price($new);$product->save();$r['updated']++;$r['items'][]=['id'=>$id,'title'=>$product->get_name(),'old'=>$old,'new'=>$new];}else$r['unchanged']++;}wp_reset_postdata();$r['seconds']=round(microtime(true)-$start,2);self::log(['price_sync'=>1,'checked'=>$r['checked'],'updated'=>$r['updated'],'unchanged'=>$r['unchanged'],'missing'=>$r['missing'],'errors'=>$r['errors'],'seconds'=>$r['seconds']]);return$r;}
 private static function discover(){$s=self::settings();$urls=[];$seen=[];$queue=[$s['source'].'/robots.txt',$s['source'].'/sitemap_index.xml',$s['source'].'/sitemap.xml',$s['source'].'/product-sitemap.xml'];while($queue&&count($seen)<50){$map=self::safe_url(array_shift($queue));if(!$map||isset($seen[$map]))continue;$seen[$map]=1;$body=self::get($map,true);if(is_wp_error($body))continue;$path=wp_parse_url($map,PHP_URL_PATH)?:'';if('robots.txt'===basename($path)){if(preg_match_all('/^\s*Sitemap:\s*(\S+)\s*$/mi',$body,$m))foreach($m[1]as$x){$x=self::safe_url(trim($x));if($x)$queue[]=$x;}continue;}if(preg_match_all('/<loc>\s*(.*?)\s*<\/loc>/is',$body,$m))foreach($m[1]as$loc){$loc=self::safe_url(html_entity_decode(trim($loc)));if(!$loc)continue;$p=wp_parse_url($loc,PHP_URL_PATH)?:'';if(preg_match('~/product/\d+(?:/|$)~i',$p))$urls[$loc]=1;elseif(preg_match('/sitemap/i',$loc))$queue[]=$loc;}}if(empty($urls)){$body=self::get($s['source'].'/product/',true);if(!is_wp_error($body)&&preg_match_all('/href\s*=\s*["\']([^"\']*\/product\/[^"\']*)["\']/i',$body,$m))foreach($m[1]as$x){$x=self::abs($s['source'].'/product/',$x);if($x)$urls[$x]=1;}}update_option(self::QUEUE,array_keys($urls),false);}
 private static function scrape($url){$html=self::get($url);if(is_wp_error($html))return$html;$dom=self::dom($html);$json=self::jsonld_products($dom);$title=$json['name']?:self::xpath_text($dom,['//h1','//meta[@property="og:title"]/@content','//title']);$description=$json['description']?:self::xpath_html($dom,['//*[@itemprop="description"]','//*[contains(concat(" ",normalize-space(@class)," ")," description ")]','//*[contains(concat(" ",normalize-space(@class)," ")," product-description ")]']);$price=$json['price'];if(''===$price)$price=self::xpath_attr_or_text($dom,['//*[@itemprop="price"]','//*[contains(concat(" ",normalize-space(@class)," ")," price ")]'],'content');$brand=$json['brand']?:self::xpath_text($dom,['//*[@itemprop="brand"]']);$sku=$json['sku']?:self::xpath_attr_or_text($dom,['//*[@itemprop="sku"]'],'content');$category=$json['category']?:self::xpath_text($dom,['//*[@itemprop="category"]']);$images=$json['images'];if(empty($images))$images=self::images_from_dom($dom,$url);$availability=self::availability_from_jsonld($json['availability']);if(null===$availability)$availability=self::availability_from_dom($dom,$html);if(!$title)return new WP_Error('title_missing','عنوان محصول پیدا نشد.');if(null===$availability)return new WP_Error('availability_unknown','وضعیت موجودی نامشخص');return['url'=>$url,'title'=>self::clean($title),'description'=>wp_kses_post($description),'price'=>self::money($price),'brand'=>self::clean($brand),'sku'=>self::clean($sku),'category'=>self::clean($category),'images'=>array_slice(array_values(array_unique(array_filter($images))),0,self::settings()['image_limit']),'available'=>(bool)$availability];}
 private static function import($p,$sid){if(self::find_product_id($sid,$p['url']))return new WP_Error('duplicate','قبلاً وارد شده');$product=new WC_Product_Simple();$product->set_name($p['title']);$product->set_description($p['description']);$product->set_status(self::settings()['publish']?'publish':'draft');$product->set_catalog_visibility('visible');$product->set_stock_status('instock');if($p['price']!=='')$product->set_regular_price($p['price']);if($p['sku']&&!wc_get_product_id_by_sku($p['sku']))$product->set_sku($p['sku']);$id=$product->save();if(!$id)return new WP_Error('save_failed','ذخیره ناموفق');update_post_meta($id,'_hamnna_scraper_schema',self::SCHEMA);update_post_meta($id,'_hamnna_source_id',$sid);update_post_meta($id,'_hamnna_source_url',esc_url_raw($p['url']));update_post_meta($id,'_hamnna_imported_at',current_time('mysql'));if($p['brand']){update_post_meta($id,'_hamnna_brand',$p['brand']);self::assign_brand($id,$p['brand']);}if($p['category'])self::assign_category($id,$p['category']);if(self::settings()['import_images']&&!empty($p['images']))self::images($p['images'],$id);return$id;}
 private static function assign_category($id,$source){$parts=preg_split('/\s*[›»|\/>]\s*/u',trim(preg_replace('/\s+/u',' ',$source)));$name=trim(end($parts));if(!$name)return;$term=term_exists($name,'product_cat');if(!$term)$term=wp_insert_term($name,'product_cat');if(!is_wp_error($term)&&$term)wp_set_object_terms($id,[(int)(is_array($term)?$term['term_id']:$term)],'product_cat',false);}
 private static function assign_brand($id,$brand){foreach(['product_brand','pwb-brand','brand']as$tax){if(!taxonomy_exists($tax))continue;$term=term_exists($brand,$tax);if(!$term)$term=wp_insert_term($brand,$tax);if(!is_wp_error($term)&&$term)wp_set_object_terms($id,[(int)(is_array($term)?$term['term_id']:$term)],$tax,false);break;}}
 private static function images($urls,$pid){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$ids=[];foreach($urls as$url){$url=self::safe_url($url);if(!$url)continue;$tmp=download_url($url,self::settings()['http_timeout']);if(is_wp_error($tmp))continue;$size=@filesize($tmp);if($size&&$size>15*1024*1024){@unlink($tmp);continue;}$name=sanitize_file_name(basename(wp_parse_url($url,PHP_URL_PATH)?:'hamnna.jpg'));if(!preg_match('/\.(jpe?g|png|gif|webp)$/i',$name))$name.='.jpg';$id=media_handle_sideload(['name'=>$name,'tmp_name'=>$tmp],$pid);if(is_wp_error($id)){@unlink($tmp);continue;}$ids[]=$id;}if($ids){set_post_thumbnail($pid,$ids[0]);if(count($ids)>1)update_post_meta($pid,'_product_image_gallery',implode(',',array_map('absint',array_slice($ids,1))));}}
 private static function find_product_id($sid,$url){$q=new WP_Query(['post_type'=>'product','post_status'=>'any','fields'=>'ids','posts_per_page'=>1,'no_found_rows'=>true,'meta_query'=>['relation'=>'OR',['key'=>'_hamnna_source_id','value'=>(string)$sid],['key'=>'_hamnna_source_url','value'=>$url]]]);return empty($q->posts)?0:(int)$q->posts[0];}
 private static function exists($sid,$url){return(bool)self::find_product_id($sid,$url);}
 private static function source_id($url){$p=wp_parse_url($url,PHP_URL_PATH)?:$url;return preg_match('~/product/(\d+)~i',$p,$m)?$m[1]:md5(untrailingslashit($p));}
 private static function get($url,$text=false){$url=self::safe_url($url);if(!$url)return new WP_Error('unsafe_url','URL غیرمجاز');$r=wp_remote_get($url,['timeout'=>self::settings()['http_timeout'],'redirection'=>0,'user-agent'=>'Hamnna Product Scraper/'.HAMNNA_SCRAPER_VERSION,'headers'=>['Accept-Language'=>'fa-IR,fa;q=0.9,en;q=0.8','Accept'=>$text?'text/plain,application/xml,text/xml,text/html;q=0.9':'text/html,application/xhtml+xml;q=0.9'],'limit_response_size'=>8*1024*1024]);if(is_wp_error($r))return$r;$c=(int)wp_remote_retrieve_response_code($r);if($c>=300&&$c<400)return new WP_Error('redirect_rejected','Redirect رد شد');if($c<200||$c>=300)return new WP_Error('http_'.$c,'HTTP '.$c);return wp_remote_retrieve_body($r);}
 private static function safe_url($url){$url=esc_url_raw(trim((string)$url));$p=wp_parse_url($url);if(!$p||strtolower($p['scheme']??'')!=='https')return'';$h=strtolower(rtrim($p['host']??'','.'));if($h!==self::SOURCE_HOST&&!preg_match('/(^|\.)'.preg_quote(self::SOURCE_HOST,'/').'$/i',$h))return'';return$url;}
 private static function normalize_product_url($url){$url=self::safe_url($url);$path=wp_parse_url($url,PHP_URL_PATH)?:'';return preg_match('~/product/\d+(?:/|$)~i',$path)?'https://'.self::SOURCE_HOST.untrailingslashit($path).'/':'';}
 private static function abs($base,$url){$url=trim(html_entity_decode($url));if(preg_match('~^https?://~i',$url))return self::safe_url($url);if(strpos($url,'//')===0)return self::safe_url('https:'.$url);$b=wp_parse_url($base);if(!$b||empty($b['host']))return'';$root='https://'.$b['host'];if(strpos($url,'/')===0)return self::safe_url($root.$url);return self::safe_url($root.trailingslashit(dirname($b['path']??'/')).$url);}
 private static function dom($html){$d=new DOMDocument();$e=libxml_use_internal_errors(true);$d->loadHTML('<?xml encoding="utf-8"?>'.$html,LIBXML_NOWARNING|LIBXML_NOERROR|LIBXML_NONET);libxml_clear_errors();libxml_use_internal_errors($e);return$d;}
 private static function xpath_nodes($d,$qs){$x=new DOMXPath($d);foreach($qs as$q){$n=$x->query($q);if($n&&$n->length)return$n;}return null;}
 private static function xpath_text($d,$qs){$n=self::xpath_nodes($d,$qs);return$n?trim(preg_replace('/\s+/u',' ',$n->item(0)->nodeValue)):'';}
 private static function xpath_attr_or_text($d,$qs,$a){$n=self::xpath_nodes($d,$qs);if(!$n)return'';$x=$n->item(0);return trim($x->attributes&&$x->attributes->getNamedItem($a)?$x->attributes->getNamedItem($a)->nodeValue:$x->nodeValue);}
 private static function xpath_html($d,$qs){$n=self::xpath_nodes($d,$qs);if(!$n)return'';$o='';foreach($n->item(0)->childNodes as$c)$o.=$n->item(0)->ownerDocument->saveHTML($c);return trim($o);}
 private static function jsonld_products($d){$o=['name'=>'','description'=>'','price'=>'','brand'=>'','sku'=>'','category'=>'','images'=>[],'availability'=>''];foreach($d->getElementsByTagName('script')as$t){if(strtolower(trim($t->getAttribute('type')))!='application/ld+json')continue;$z=json_decode(trim($t->textContent),true);if(!is_array($z))continue;$items=isset($z['@graph'])&&is_array($z['@graph'])?$z['@graph']:(isset($z[0])?$z:[$z]);foreach($items as$i){if(!is_array($i)||!in_array('Product',(array)($i['@type']??[]),true))continue;$o['name']=$o['name']?:($i['name']??'');$o['description']=$o['description']?:($i['description']??'');$o['sku']=$o['sku']?:($i['sku']??'');$b=$i['brand']??'';$o['brand']=$o['brand']?: (is_array($b)?($b['name']??''):$b);$o['category']=$o['category']?:($i['category']??'');$im=$i['image']??[];if(is_string($im))$im=[$im];foreach((array)$im as$x){$x=self::safe_url($x);if($x)$o['images'][]=$x;}$of=$i['offers']??[];if(isset($of[0]))$of=$of[0];if(is_array($of)){$o['price']=$o['price']?:($of['price']??'');$o['availability']=$o['availability']?:($of['availability']??'');}}}return$o;}
 private static function availability_from_jsonld($a){$a=strtolower(trim((string)$a));if(!$a)return null;if(strpos($a,'outofstock')!==false||strpos($a,'soldout')!==false||strpos($a,'discontinued')!==false)return false;if(strpos($a,'instock')!==false||strpos($a,'limitedavailability')!==false)return true;return null;}
 private static function availability_from_dom($d,$h){$x=new DOMXPath($d);$n=$x->query('//*[@itemprop="availability"]/@href|//*[@itemprop="availability"]');if($n&&$n->length){$r=self::availability_from_jsonld($n->item(0)->nodeValue);if($r!==null)return$r;}$b=mb_strtolower(wp_strip_all_tags($h),'UTF-8');foreach(['اتمام موجودی','تمام شده','ناموجود','نا موجود','out of stock','unavailable','sold out']as$w)if(mb_strpos($b,$w)!==false)return false;foreach(['افزودن به سبد خرید','افزودن به سبد','خرید محصول','in stock','add to cart']as$w)if(mb_strpos($b,$w)!==false)return true;return null;}
 private static function images_from_dom($d,$u){$a=[];foreach($d->getElementsByTagName('img')as$i)foreach(['data-src','data-lazy-src','src']as$k){$x=$i->getAttribute($k);if($x){$x=self::abs($u,$x);if($x)$a[]=$x;break;}}return array_values(array_unique($a));}
 private static function money($v){$v=html_entity_decode((string)$v,ENT_QUOTES,'UTF-8');$v=strtr($v,['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9','٬'=>',']);$v=preg_replace('/(تومان|تومن|ریال|ريال|﷼|IRT|IRR)/iu','',$v);$v=trim(preg_replace('/[^0-9,.]/u','',$v));if($v==='')return'';$lastComma=strrpos($v,',');$lastDot=strrpos($v,'.');if($lastComma===false&&$lastDot===false)return preg_replace('/\D/','',$v);$last=max($lastComma===false?-1:$lastComma,$lastDot===false?-1:$lastDot);$suffix=preg_replace('/\D/','',substr($v,$last+1));$prefix=preg_replace('/\D/','',substr($v,0,$last));if(strlen($suffix)===3){$v=$prefix.$suffix;}else{$v=$prefix.'.'.$suffix;}return(string)round((float)$v);}
 private static function clean($s){return trim(preg_replace('/\s+/u',' ',wp_strip_all_tags((string)$s)));}
 private static function debug_log($a,$u,$m){if(self::settings()['debug'])self::log(['stage'=>$a,'url'=>$u,'message'=>$m]);}
 private static function log($e){$l=get_option(self::LOG,[]);if(!is_array($l))$l=[];$e['time']=current_time('mysql');array_unshift($l,$e);update_option(self::LOG,array_slice($l,0,100),false);}
}